//! Embedded official Microsoft Fluent System Icons (20px regular) used by Explorer chrome.

use std::borrow::Cow;

use gpui::{AssetSource, SharedString};

#[derive(Clone, Copy, Debug, Default)]
pub struct ExplorerAssets;

impl AssetSource for ExplorerAssets {
    fn load(&self, path: &str) -> gpui::Result<Option<Cow<'static, [u8]>>> {
        if path == "lua/logo.gif" {
            return Ok(Some(Cow::Owned(decode_base64(LUA_LOGO_GIF_BASE64))));
        }
        let Some(name) = path
            .strip_prefix("fluent/")
            .and_then(|path| path.strip_suffix(".svg"))
        else {
            return Ok(None);
        };
        Ok(fluent_path(name).map(|data| {
            Cow::Owned(
                format!(
                    r#"<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="{data}" fill="currentColor"/></svg>"#
                )
                .into_bytes(),
            )
        }))
    }

    fn list(&self, path: &str) -> gpui::Result<Vec<SharedString>> {
        if path != "fluent" {
            return Ok(Vec::new());
        }
        Ok(crate::icons::ExplorerIcon::ALL
            .into_iter()
            .map(|icon| SharedString::from(icon.asset_path()))
            .collect())
    }
}

// Official Lua logo from https://www.lua.org/images/lua-logo.gif.
// Copyright (c) 1998 Lua.org; graphic design by Alexandre Nakonechnyj.
// Embedded unchanged under the logo permission published at https://www.lua.org/images/.
const LUA_LOGO_GIF_BASE64: &str = "";

fn decode_base64(input: &str) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len() * 3 / 4);
    let mut accumulator = 0_u32;
    let mut bits = 0_u8;
    for byte in input.bytes() {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            _ => continue,
        };
        accumulator = (accumulator << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            output.push((accumulator >> bits) as u8);
            accumulator &= (1_u32 << bits).saturating_sub(1);
        }
    }
    output
}

