#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_explorer_icon_has_embedded_offline_svg() {
        let assets = ExplorerAssets;
        for icon in crate::icons::ExplorerIcon::ALL {
            let data = assets.load(&icon.asset_path()).unwrap().unwrap();
            let text = std::str::from_utf8(&data).unwrap();
            assert!(text.contains("<svg"));
            assert!(text.contains("currentColor"));
        }
    }

    #[test]
    fn official_lua_logo_is_embedded_offline_as_the_original_gif() {
        let data = ExplorerAssets.load("lua/logo.gif").unwrap().unwrap();
        assert_eq!(&data[..6], b"GIF87a");
        assert_eq!(data.len(), 4_232);
    }
}
